package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Repair-parts catalog/inventory. Barcode is first-class and stock changes are transactional. */
public final class RepairPartStore {
 private final CoreStore.DbProvider provider;private final String deviceId;
 public RepairPartStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public static final class SearchResult{public final String partId,name,barcode,currency;public final int quantity;public final double salePrice,unitCost;SearchResult(String id,String n,String b,int q,double sp,double uc,String c){partId=id;name=n;barcode=b;quantity=q;salePrice=sp;unitCost=uc;currency=c;}}
 public List<SearchResult> search(String query,int limit){String q=trim(query);if(q.isEmpty())return new ArrayList<>();int max=Math.max(1,Math.min(limit,50));String like="%"+q.replace("%","\\%").replace("_","\\_")+"%";ArrayList<SearchResult> out=new ArrayList<>();try(Cursor c=provider.db().rawQuery("SELECT part_id,name,barcode,quantity,sale_price,unit_cost,currency FROM repair_inventory WHERE deleted_at IS NULL AND (name LIKE ? ESCAPE '\\' COLLATE NOCASE OR barcode LIKE ? ESCAPE '\\' OR part_id LIKE ? ESCAPE '\\') ORDER BY CASE WHEN barcode=? THEN 0 WHEN name=? COLLATE NOCASE THEN 1 ELSE 2 END,name LIMIT "+max,new String[]{like,like,like,q,q})){while(c.moveToNext())out.add(new SearchResult(c.getString(0),c.getString(1),c.getString(2),c.getInt(3),c.getDouble(4),c.getDouble(5),c.getString(6)));}return out;}
 public String save(String partId,String name,String barcode,int quantity,double cost)throws Exception{String n=req(name,"اسم القطعة"),b=trim(barcode);if(quantity<0||cost<0)throw new IllegalArgumentException("الكمية أو التكلفة غير صالحة");long now=System.currentTimeMillis();String id=trim(partId);boolean create=id.isEmpty();if(create)id="part-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{if(!b.isEmpty()){try(Cursor c=db.rawQuery("SELECT part_id FROM repair_inventory WHERE barcode=? AND deleted_at IS NULL AND part_id<>? LIMIT 1",new String[]{b,id})){if(c.moveToFirst())throw new IllegalArgumentException("يوجد جزء صيانة بنفس الباركود");}}ContentValues v=new ContentValues();v.put("name",n);v.put("barcode",b);v.put("quantity",quantity);v.put("unit_cost",cost);v.put("updated_at",now);if(create){v.put("part_id",id);v.put("sale_price",0);v.put("currency","USD");v.put("created_at",now);db.insertOrThrow("repair_inventory",null,v);}else if(db.update("repair_inventory",v,"part_id=? AND deleted_at IS NULL",new String[]{id})!=1)throw new IllegalArgumentException("قطعة الصيانة غير موجودة");JSONObject j=new JSONObject().put("partId",id).put("name",n).put("barcode",b).put("quantity",quantity).put("unitCost",cost).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SETTING,id,j.toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public int adjust(String partId,int delta,String sourceType,String sourceId)throws Exception{if(delta==0)throw new IllegalArgumentException("التغيير يجب ألا يكون صفراً");SQLiteDatabase db=provider.db();db.beginTransaction();try{int before;try(Cursor c=db.rawQuery("SELECT quantity FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{partId})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");before=c.getInt(0);}int after=before+delta;if(after<0)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("quantity",after);v.put("updated_at",now);db.update("repair_inventory",v,"part_id=?",new String[]{partId});String move="partmove-"+UUID.randomUUID();ContentValues mv=new ContentValues();mv.put("move_id",move);mv.put("part_id",partId);mv.put("source_type",trim(sourceType));mv.put("source_id",trim(sourceId));mv.put("before_qty",before);mv.put("delta_qty",delta);mv.put("after_qty",after);mv.put("created_at",now);db.insertOrThrow("repair_inventory_moves",null,mv);JSONObject j=new JSONObject().put("partId",partId).put("before",before).put("delta",delta).put("after",after).put("sourceType",trim(sourceType)).put("sourceId",trim(sourceId)).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SETTING,move,j.toString(),deviceId));db.setTransactionSuccessful();return after;}finally{db.endTransaction();}}
 private static String req(String v,String label){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(label+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}
}
